flake.nix


```nix
{
  description = "Scopes programming language";

  inputs = {
    nixpkgs.url = "github:NixOS/nixpkgs/nixos-unstable";
    flake-utils.url = "github:numtide/flake-utils";
  };

  outputs = { self, nixpkgs, flake-utils }:
    flake-utils.lib.eachDefaultSystem (system:
      let
        pkgs = import nixpkgs {
          inherit system;
        };
        llvm = pkgs.llvmPackages_16;
        scopes = pkgs.stdenv.mkDerivation rec {
          pname = "scopes";
          version = "0";

          src = pkgs.fetchFromGitHub {
            owner = "Fundament-Software";
            repo = "scopes";
            rev = "main";
            sha256 = "sha256-AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA="; # Frissíteni build-kor
          };

          nativeBuildInputs = with pkgs; [
            cmake
            ninja
            clang_16
            llvm.lld_16
          ];

          buildInputs = with pkgs; [
            llvm.libclang
            llvm.llvm
            zlib
            libffi
            openssl
            bzip2
            xz
          ];

          env = {
            NIX_CFLAGS_COMPILE = toString (with llvm; [
              "-I${libclang.lib}/lib/clang/${libclang.version}/include"
            ]);
            CC = "clang";
            CXX = "clang++";
            LLD = "${llvm.lld_16}/bin/ld.lld";
          };

          cmakeFlags = [
            "-DCMAKE_BUILD_TYPE=Release"
            "-DCMAKE_C_COMPILER=clang"
            "-DCMAKE_CXX_COMPILER=clang++"
            "-DLLVM_DIR=${llvm.lib}/lib/cmake/llvm"
            "-DClang_DIR=${llvm.libclang.lib}/lib/cmake/clang"
          ];

          doCheck = true;

          meta = with pkgs.lib; {
            description = "Scopes programming language";
            homepage = "";
            license = licenses.mit;
            maintainers = [ ];
            platforms = platforms.unix;
          };
        };
      in
      {
        packages.default = scopes;
        devShells.default = pkgs.mkShell {
          inputsFrom = [ scopes ];
          buildInputs = [
            pkgs.replit-nix
          ];
        };
        apps.default = flake-utils.lib.mkApp {
          drv = scopes;
          exePath = "/bin/scopes";
        };
      });
}

