```nix
{
  description = "Scopes programming language";

  inputs = {
    nixpkgs.url = "github:NixOS/nixpkgs/nixos-25.05";
    flake-utils.url = "github:numtide/flake-utils";
    scopes-src = {
      url = "github:Fundament-Software/scopes";
      flake = false;
    };
  };

  outputs = { self, nixpkgs, flake-utils, scopes-src }:
    flake-utils.lib.eachDefaultSystem (system:
      let
        pkgs = import nixpkgs { inherit system; };
        llvm = pkgs.llvmPackages_16;

        scopes = llvm.stdenv.mkDerivation {
          pname = "scopes";
          version = "git";

          src = scopes-src;

          nativeBuildInputs = [
            pkgs.cmake
            pkgs.ninja
            pkgs.pkg-config
            llvm.clang
            llvm.lld
          ];

          buildInputs = [
            llvm.llvm
            llvm.libclang
            pkgs.zlib
            pkgs.libffi
            pkgs.openssl
            pkgs.bzip2
            pkgs.xz
          ];

          cmakeFlags = [
            "-DCMAKE_BUILD_TYPE=Release"
            "-DCMAKE_C_COMPILER=${llvm.clang}/bin/clang"
            "-DCMAKE_CXX_COMPILER=${llvm.clang}/bin/clang++"
            "-DLLVM_DIR=${llvm.llvm.dev}/lib/cmake/llvm"
            "-DClang_DIR=${llvm.clang.dev}/lib/cmake/clang"
          ];

          installPhase = ''
            runHook preInstall
            cmake --install . --prefix "$out"
            runHook postInstall
          '';

          meta = with pkgs.lib; {
            description = "Scopes programming language";
            homepage = "";
            license = licenses.mit;
            platforms = platforms.unix;
            mainProgram = "scopes";
          };
        };
      in
      {
        packages.default = scopes;

        apps.default = {
          type = "app";
          program = "${scopes}/bin/${scopes.meta.mainProgram}";
        };

        devShells.default = pkgs.mkShell {
          packages = [
            pkgs.git
            pkgs.cmake
            pkgs.ninja
            pkgs.pkg-config
            llvm.clang
            llvm.lld
          ];
        };
      });
}
